package com.saasquatch.intelligence.service; import com.saasquatch.intelligence.entity.*; import com.saasquatch.intelligence.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class CorporateRelationshipService { private final CorporateRelationshipRepository repo; public CorporateRelationshipService(CorporateRelationshipRepository repo){this.repo=repo;} public List<CorporateRelationship> forCompany(Long id){return repo.findByCompanyId(id);} }